/** Frameworks from 0.4.0 carry the owner's approvals in their "approve framing" and "approve addition" Checks. */
const frameworkFrom = (plan, from) =>
  plan.procedure === FRAMEWORK &&
  (([major, minor]) => major > 0 || minor >= from)(String(plan.procedureVersion).split(".").map(Number));
const governs = (plan) => frameworkFrom(plan, 4);

function revisionApprovals(root) {
  if (!evolves(root.plan)) return [];
  const check = checkNamed(root.checks, "approve revision");
  const facts = (check?.attempts ?? []).flatMap((attempt) => attempt.facts ?? []);
  return (check?.history ?? [])
    .filter((qualification) => qualification.verdict === "VALIDATED")
    .flatMap((qualification) => facts.filter((fact) => qualification.factIds.includes(fact.id)))
    .map((fact) => ({
      thread: fact.values?.thread,
      state: "SATISFIED",
      plan: root.plan.plan,
      revision: fact.values?.revision,
      choice: "continue",
      approved: fact.values?.revision,
    }));
}

