if (governed && !governed.evolving && !governed.single && !governed.ended) {
  const proposed = { ...t, requirements: parseRequirements(a.body).requirements };
  // Technical blocks evolve through approved revisions (the registry); only requirement blocks are frozen here.
  const { changed, removed } = await approvalReview(db, proposed, governed.approvals, { evolving: false });
  if (changed.length || removed.length)
    conflict(
      `Approved requirements cannot be changed or removed: ${findingsReport({ unapproved: [], changed, removed })}. A change goes through a new requirement.`,
    );
}

